delete SYS_DATADICT a where a.system_code='SYS';
delete
   from sys_datadict_list b
  where b.dict_code in
        (select a.dict_code from sys_datadict a where a.system_code = 'SYS');
delete SYS_USER where user_id in('00000000000000000001','00000000000000000002');
delete SYS_PAGE_ELEMENT b where b.page_id in(
 select a.page_id from  SYS_MENU a where a.system_code='SYS');
delete SYS_MENU a where a.system_code='SYS';
delete sys_page a where a.system_code='SYS';
 delete sys_para a where a.system_code='SYS';
delete  from SYS_WFL_BUSINESS_MODULE;
commit;